pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        address actor = address(0x1234);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        // General rule: a successful fallback call must carry exactly 10 ether.
        assertTrue(!ok || amount == 10 ether);
    }
}
